CREATE INDEX idx_task_notes_task ON task_notes(task_id);
CREATE INDEX idx_task_files_task ON task_files(task_id);
CREATE INDEX idx_task_files_path ON task_files(path);
CREATE INDEX idx_learnings_project ON learnings(project_id);
